window.onerror=function(m){try{window.__zjt='JSERR:'+m;}catch(e){}};
function b64d(s){var bin=atob(s);var u=new Uint8Array(bin.length);for(var i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);return u;}
function b64e(u){var s='';for(var i=0;i<u.length;i++)s+=String.fromCharCode(u[i]);return btoa(s);}
function hex(u){var s='',i;for(i=0;i<u.length;i++){var h=u[i].toString(16);if(h.length<2)h='0'+h;s+=h;}return s;}
var AESKEY=null,HMACKEY=null;
async function setupKeys(){
  var km=b64d(KM);
  var hk=await crypto.subtle.importKey('raw',km,'HKDF',false,['deriveBits']);
  var as=await crypto.subtle.deriveBits({name:'HKDF',hash:'SHA-256',salt:new TextEncoder().encode(SID),info:new TextEncoder().encode('novel-api-aes-v1')},hk,256);
  AESKEY=await crypto.subtle.importKey('raw',as,'AES-GCM',false,['encrypt','decrypt']);
  var hs=await crypto.subtle.deriveBits({name:'HKDF',hash:'SHA-256',salt:new TextEncoder().encode(SID),info:new TextEncoder().encode('novel-hmac-v1')},hk,256);
  HMACKEY=await crypto.subtle.importKey('raw',hs,{name:'HMAC',hash:'SHA-256'},false,['sign']);
}
async function decj(j){
  if(j&&j.version===1){ try{ var pt=await crypto.subtle.decrypt({name:'AES-GCM',iv:b64d(j.nonce),tagLength:128},AESKEY,b64d(j.data)); j.obj=JSON.parse(new TextDecoder().decode(pt)); }catch(e){ j.decerr=String(e&&e.message?e.message:e); } }
  return j;
}
async function api(path,body){
  var iv=crypto.getRandomValues(new Uint8Array(12));
  var ct=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv:iv,tagLength:128},AESKEY,new TextEncoder().encode(JSON.stringify(body))));
  var env=JSON.stringify({version:1,algorithm:'AES-256-GCM',data:b64e(ct),nonce:b64e(iv)});
  var ts=String(Math.floor(Date.now()/1000));
  var no=b64e(crypto.getRandomValues(new Uint8Array(18))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=/g,'');
  var bh=hex(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(env))));
  var msg=['POST',path,ts,no,bh,SID].join(String.fromCharCode(10));
  var sg=b64e(new Uint8Array(await crypto.subtle.sign('HMAC',HMACKEY,new TextEncoder().encode(msg))));
  var ac=new AbortController();var tm=setTimeout(function(){try{ac.abort();}catch(e){}},15000);
  var r;try{r=await fetch(ZJB+path,{method:'POST',headers:{'Content-Type':'application/json','X-Session-ID':SID,'X-Timestamp':ts,'X-Nonce':no,'X-Signature':sg,'X-Key-Version':'1'},body:env,signal:ac.signal});}finally{clearTimeout(tm);}
  return await decj(await r.json());
}
function loadTs(){
  return new Promise(function(res,rej){
    if(window.turnstile&&typeof window.turnstile.render==='function')return res();
    if(window.__zjts){ var t=setInterval(function(){if(window.turnstile&&typeof window.turnstile.render==='function'){clearInterval(t);res();}},120); return; }
    window.__zjts=1;
    var s=document.createElement('script');
    s.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';
    s.async=true;s.defer=true;
    s.onload=function(){var t=setInterval(function(){if(window.turnstile&&typeof window.turnstile.render==='function'){clearInterval(t);res();}},100);setTimeout(function(){clearInterval(t);if(window.turnstile&&window.turnstile.render)res();else rej(new Error('turnstile not ready'));},15000);};
    s.onerror=function(){rej(new Error('turnstile load fail'));};
    document.head.appendChild(s);
  });
}
function getToken(key){
  return new Promise(function(res,rej){
    loadTs().then(function(){
      var gt=0;function go(){ try{ window.turnstile.render(cf,{sitekey:key,callback:function(t){res(t);}}); }catch(e){ if(++gt<50) setTimeout(go,200); else rej(new Error('turnstile render fail')); } }
      try{ if(window.turnstile&&window.turnstile.ready) window.turnstile.ready(go); else go(); }catch(e){ go(); }
    }).catch(rej);
  });
}
