    await setupKeys();
    var cfg=await api('/api/config',{});
    var d=(cfg&&cfg.obj&&cfg.obj.data)||{};
    var body={chapter_id:CID};
    if(d.content_captcha&&!d.content_verified){
      out.textContent='请完成人机验证，验证通过后会自动继续…';
      body.turnstile_token=await getToken(d.captcha_site_key);
    }
    var z=await api('/api/book/content',body);
    var ok=(z&&z.key_mode==='chapter')||(z&&z.obj&&String(z.obj.code)==='0');
    document.documentElement.setAttribute('data-ver', ok?'1':'0');
    out.textContent=ok?'验证完成，正在继续…':'验证未通过，可返回后重试';
    setTimeout(function(){try{window.close();}catch(e){}},ok?500:2500);
  }catch(e){ out.textContent='验证出错：'+e; document.documentElement.setAttribute('data-ver','0'); setTimeout(function(){try{window.close();}catch(e){}},2500); }
})();
