source.bookSourceComment:
// Error: 发现失效, 搜索失效


◇默认搜索开启
◇如需开启获取评论（开启后速度有影响，默认获取15条评论） 
◇点击设置源变量填写数字1确认，刷新，有缓存的章节也需要刷新
◇数字1开启评论  ，不填则是关闭
◇默认关闭
<js>
//去除章节简介与正文重复
if(/^◌/.test(result) ){
chapter = result.match(/◌([\s\S]+?)…*．/)[1].replace(/\s/g,'');
chapter2=result.match(/◌[\s\S]+?．([\s\S]+)/)[1].replace(/\s/g,'');
//前十个字相同就删除
num = 10
if(chapter.substring(0,num)==chapter2.substring(0,num)){
	result = result.replace(/◌[\s\S]+?．/,'')
	}else{result}
}else{result}
</js>

